glsl:
#version 450
layout(std140, set = 0, binding = 0) uniform NrUniforms { vec2 u_res; float u_time; vec3 u_tint; float u_mix; int u_on_nrb; vec4 nr_unit; }; layout(set = 0, binding = 1) uniform texture2D u_shape_nrt; layout(set = 0, binding = 2) uniform sampler u_shape_nrs; layout(location = 0) out vec4 nr_FragColor; vec4 nr_FragCoord;


















vec3 shade(vec3 c) { return c * 0.5; }
vec2 shade(vec2 c) { return c; }
void nr_main() {
  vec2 uv = nr_FragCoord.xy / u_res;
  float d = texture(sampler2D(u_shape_nrt, u_shape_nrs), uv).r;
  vec2 size = vec2(textureSize(sampler2D(u_shape_nrt, u_shape_nrs), 0));
  vec3 c = uv.x < 0.5 ? u_tint : vec3(0.0, uv.y, u_mix);
  if (!bool(u_on_nrb)) { c = shade(c); }
  nr_FragColor = vec4(c, d > 0.0 && size.x > 0.0 ? 1.0 : 0.0);
}

void main() { nr_FragCoord = vec4(gl_FragCoord.x * nr_unit.x, nr_unit.z - gl_FragCoord.y * nr_unit.y, 0.0, 1.0); nr_FragColor = vec4(0.0); nr_main(); }
